#include <vector>
#include <cmath>

class Solution {
private:
    int digitSum(long long x) {
        x = std::abs(x);
        int s = 0;
        while (x > 0) {
            s += x % 10;
            x /= 10;
        }
        return s;
    }
public:
    int countSubarraysWithMatchingSumDigits(std::vector<int>& nums, int targetDigitSum) {
        int n = nums.size();
        int ans = 0;
        for (int i = 0; i < n; ++i) {
            long long cur = 0;
            for (int j = i; j < n; ++j) {
                cur += nums[j];
                if (digitSum(cur) == targetDigitSum) ans++;
            }
        }
        return ans;
    }
};

class Solution {
    private int digitSum(long x) {
        x = Math.abs(x);
        int s = 0;
        while (x > 0) {
            s += (int)(x % 10);
            x /= 10;
        }
        return s;
    }

    public int countSubarraysWithMatchingSumDigits(int[] nums, int targetDigitSum) {
        int n = nums.length;
        int ans = 0;
        for (int i = 0; i < n; i++) {
            long cur = 0;
            for (int j = i; j < n; j++) {
                cur += nums[j];
                if (digitSum(cur) == targetDigitSum) ans++;
            }
        }
        return ans;
    }
}

